    int64_t N, int64_t Co, int64_t Ho, int64_t Wo, int64_t Ci, int64_t Hi, int64_t Wi, int64_t Kh, int64_t Kw) {
    size_t idx = size_t(blockIdx.x) * size_t(blockDim.x) + size_t(threadIdx.x);
    size_t stride_nchw = size_t(Co) * size_t(Ho) * size_t(Wo);
    if (idx >= size_t(N) * stride_nchw) return;
    size_t temp = idx % stride_nchw;
    int64_t n = idx / stride_nchw;
    int64_t c = temp / (size_t(Ho) * Wo);
    int64_t hw = temp % (size_t(Ho) * Wo);
    int64_t h = hw / Wo;
    int64_t w = hw % Wo;
    float acc = bias[c];
    for (int64_t ci = 0; ci < Ci; ++ci) {
        for (int64_t kh = 0; kh < Kh; ++kh) {
            int64_t ih = h + kh;
            for (int64_t kw = 0; kw < Kw; ++kw) {
                int64_t iw = w + kw;
                float i_val = input[(n * Ci + ci) * Hi * Wi + ih * Wi + iw];
                float w_val = weight[(c * Ci + ci) * Kh * Kw + kh * Kw + kw];
                acc += i_val * w_val;
            }
        }
    }
    float x = acc;
    float sp = (x > 0.0f) ? (x + log1pf(expf(-x))) : log1pf(expf(x));
    float t = tanhf(sp);
    output[(n * Co + c) * Ho * Wo + h * Wo + w] = t * x;
}

torch::Tensor fused_conv_act_hip(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    int64_t N = input.size(0);
    int64_t Ci = input.size(1);
    int64_t Hi = input.size(2);
    int64_t Wi = input.size(3);
    int64_t Co = weight.size(0);
    int64_t Kh = weight.size(2);
    int64_t Kw = weight.size(3);
    int64_t Ho = Hi - Kh + 1;
    int64_t Wo = Wi - Kw + 1;
    auto output = torch::empty({N, Co, Ho, Wo}, input.options());
    const float *d_input = input.data_ptr<float>();
    const float *d_weight = weight.data_ptr<float>();
    const float *d_bias = bias.data_ptr<float>();
    float *d_output = output.data_ptr<float>();
    size_t total = size_t(N) * size_t(Co) * size_t(Ho) * size_t(Wo);
    const int threads = 256;
    dim3 block(threads);
    dim3 grid((total + threads - 1) / threads);
    fused_conv_act_kernel<<<grid, block>>>(d_input, d_weight, d_bias, d_output, N, Co, Ho, Wo, Ci, Hi, Wi, Kh, Kw);
    return output;
}
'''

